using System.Globalization;
using System.Text;
using ScratchpadLite.Core.Model;

namespace ScratchpadLite.Core.Formats.Markdown;

/// <summary>
/// Writes the IR as Markdown, by hand (Section 7.2).
/// </summary>
/// <remarks>
/// Hand-written rather than generated by Markdig, which is a reader. The
/// awkward part is escaping: Markdown has no way to quote a literal, so a
/// character that happens to be syntax has to be preceded by a backslash -
/// and escaping too much is as wrong as escaping too little, because
/// <c>\!</c> in the middle of a sentence is visible in the output of every
/// other Markdown tool.
/// <para>
/// So escaping is positional: <c>#</c> only matters at the start of a line,
/// <c>-</c> only when it would look like a list marker, and <c>.</c> only
/// after a number at the start of a line. Inline characters -
/// <c>*_`[]&lt;&gt;</c> - are escaped wherever they appear.
/// </para>
/// </remarks>
internal static class MarkdownWriter
{
    /// <summary>Where images go when a document with pictures is saved (Section 7.2).</summary>
    internal static string ImageFolderFor(string markdownPath) =>
        Path.GetFileNameWithoutExtension(markdownPath) + "_images";

    /// <summary>One image to write beside the Markdown file.</summary>
    internal sealed record Sidecar(string RelativePath, byte[] Data);

    /// <summary>
    /// Renders the document, and lists the images that have to be written
    /// beside it.
    /// </summary>
    internal static (string Text, IReadOnlyList<Sidecar> Images) Write(
        SpDocument document,
        string targetPath,
        StyleSheet styles,
        CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(document);
        ArgumentNullException.ThrowIfNull(styles);

        var text = new StringBuilder();
        var images = new List<Sidecar>();
        var folder = ImageFolderFor(targetPath);

        WriteBlocks(document.Blocks, text, images, folder, styles, depth: 0, ct);

        return (text.ToString().TrimEnd('\n') + "\n", images);
    }

    private static void WriteBlocks(
        IReadOnlyList<Block> blocks,
        StringBuilder text,
        List<Sidecar> images,
        string imageFolder,
        StyleSheet styles,
        int depth,
        CancellationToken ct)
    {
        var numbers = new Dictionary<int, int>();
        var previousWasList = false;

        foreach (var block in blocks)
        {
            ct.ThrowIfCancellationRequested();

            switch (block)
            {
                case Paragraph paragraph:
                {
                    // The line-start escaping happens here rather than inside
                    // Inline, because only out here is it known that this text
                    // begins a line.
                    var body = EscapeBlockStarts(Inline(paragraph.Inlines, images, imageFolder));

                    if (paragraph.List is { } list)
                    {
                        WriteListItem(paragraph, list, body, text, numbers);
                        previousWasList = true;
                        break;
                    }

                    // A blank line between a list and what follows it, or the
                    // next paragraph joins the last item.
                    if (previousWasList)
                    {
                        text.Append('\n');
                        numbers.Clear();
                        previousWasList = false;
                    }

                    WriteParagraph(paragraph, body, text, styles);
                    break;
                }

                case Table table:
                    if (previousWasList)
                    {
                        text.Append('\n');
                        previousWasList = false;
                    }

                    WriteTable(table, text, images, imageFolder, ct);
                    break;

                case HorizontalRule:
                    previousWasList = false;
                    text.Append("---\n\n");
                    break;
            }
        }

        _ = depth;
    }

    private static void WriteParagraph(
        Paragraph paragraph,
        string body,
        StringBuilder text,
        StyleSheet styles)
    {
        var style = styles[paragraph.StyleName];

        // Headings come from the style's outline level, so a user who renames
        // "Heading 2" in styles.json still gets "##".
        if (style.OutlineLevel is { } level)
        {
            text.Append(new string('#', Math.Clamp(level, 1, 6)))
                .Append(' ')
                .Append(body)
                .Append("\n\n");

            return;
        }

        switch (paragraph.StyleName)
        {
            case "Title":
                text.Append("# ").Append(body).Append("\n\n");
                break;

            case "Subtitle":
                text.Append("## ").Append(body).Append("\n\n");
                break;

            case "Quote":
                // Every line of a multi-line quotation needs its own marker.
                foreach (var line in body.Split('\n'))
                {
                    text.Append("> ").Append(line).Append('\n');
                }

                text.Append('\n');
                break;

            case "Code":
                text.Append("```\n").Append(body).Append("\n```\n\n");
                break;

            default:
                if (body.Length == 0)
                {
                    break;      // a blank paragraph is a blank line, and the
                                // two newlines below already provide one
                }

                text.Append(body).Append("\n\n");
                break;
        }
    }

    private static void WriteListItem(
        Paragraph paragraph,
        ListInfo list,
        string body,
        StringBuilder text,
        Dictionary<int, int> numbers)
    {
        // Four spaces a level, not two.
        //
        // A nested list has to be indented at least to its parent item's
        // content column, and less than four past it - any less and it is a
        // sibling of the parent list, any more and it is a code block. A
        // bullet's content starts at column 2 and a number's at column 3
        // ("1. "), and a wider number pushes it further out again. Four clears
        // every one of those while staying inside the code-block limit, which
        // two does not: "1. one" followed by "  - nested" is read by a
        // conforming parser as two lists rather than one.
        var indent = new string(' ', Math.Clamp(list.Level, 0, 8) * 4);

        if (list.Kind == ListKind.Bullet)
        {
            text.Append(indent).Append("- ").Append(body).Append('\n');
            return;
        }

        // Markdown has no lettered or roman lists, so a numbered list of any
        // format comes out as decimal. The save warning does not mention it,
        // because the list itself survives.
        var next = numbers.TryGetValue(list.Level, out var n)
            ? n + 1
            : Math.Max(1, list.Start);

        numbers[list.Level] = next;

        text.Append(indent)
            .Append(next.ToString(CultureInfo.InvariantCulture))
            .Append(". ")
            .Append(body)
            .Append('\n');

        _ = paragraph;
    }

    /// <summary>
    /// A pipe table. Merged cells are split, with a warning
    /// (Section 7.2).
    /// </summary>
    private static void WriteTable(
        Table table,
        StringBuilder text,
        List<Sidecar> images,
        string imageFolder,
        CancellationToken ct)
    {
        if (table.Rows.Count == 0)
        {
            return;
        }

        var columns = table.Rows.Max(r => r.Sum(c => Math.Max(1, c.ColSpan)));

        for (var r = 0; r < table.Rows.Count; r++)
        {
            ct.ThrowIfCancellationRequested();

            var cells = new List<string>(columns);

            foreach (var cell in table.Rows[r])
            {
                var content = CellText(cell, images, imageFolder);

                cells.Add(content);

                // A cell spanning columns becomes that many cells, the first
                // holding the text: a pipe table has no spans at all.
                for (var extra = 1; extra < Math.Max(1, cell.ColSpan); extra++)
                {
                    cells.Add("");
                }
            }

            while (cells.Count < columns)
            {
                cells.Add("");
            }

            text.Append("| ").Append(string.Join(" | ", cells)).Append(" |\n");

            // Markdown requires a separator row after the first row, and
            // treats the first row as a header whether it is one or not.
            if (r == 0)
            {
                text.Append("| ")
                    .Append(string.Join(" | ", Enumerable.Repeat("---", columns)))
                    .Append(" |\n");
            }
        }

        text.Append('\n');
    }

    private static string CellText(Cell cell, List<Sidecar> images, string imageFolder)
    {
        var parts = new List<string>();

        foreach (var block in cell.Blocks)
        {
            if (block is Paragraph paragraph)
            {
                var body = Inline(paragraph.Inlines, images, imageFolder);

                if (body.Length > 0)
                {
                    parts.Add(body);
                }
            }
        }

        // A newline inside a cell would end the row, so it becomes a space.
        // The pipes are already escaped: EscapeInline does it, and doing it
        // again here turned "a|b" into "a\\|b", which is a literal backslash
        // followed by the end of the cell.
        return string.Join(" ", parts).Replace("\n", " ", StringComparison.Ordinal);
    }

    private static string Inline(
        IReadOnlyList<Model.Inline> inlines,
        List<Sidecar> images,
        string imageFolder)
    {
        var text = new StringBuilder();

        foreach (var inline in inlines)
        {
            switch (inline)
            {
                case TextRun run:
                    text.Append(Run(run));
                    break;

                case Model.LineBreak:
                    // Two trailing spaces is Markdown's line break.
                    text.Append("  \n");
                    break;

                case ImageRun image:
                {
                    var name = $"image{images.Count + 1}{ExtensionFor(image.Mime)}";
                    var relative = $"{imageFolder}/{name}";

                    images.Add(new Sidecar(relative, image.Data));

                    text.Append("![")
                        .Append(EscapeInline(image.Alt))
                        .Append("](")
                        .Append(EscapeUrl(relative))
                        .Append(')');

                    break;
                }
            }
        }

        return text.ToString();
    }

    private static string Run(TextRun run)
    {
        var style = run.Style;
        var text = style.AllCapsPreserved ? run.Text.ToUpperInvariant() : run.Text;

        // A run that is only whitespace must not be wrapped in emphasis: "** **"
        // is not emphasis in any Markdown parser, it is two literal asterisks.
        if (text.Trim().Length == 0)
        {
            return text;
        }

        var escaped = EscapeInline(text);

        // Leading and trailing spaces have to sit outside the markers, for the
        // same reason.
        var leading = escaped[..(escaped.Length - escaped.TrimStart().Length)];
        var trailing = escaped[escaped.TrimEnd().Length..];
        var core = escaped.Trim();

        if (style.Strike)
        {
            core = "~~" + core + "~~";
        }

        if (style.Bold && style.Italic)
        {
            core = "***" + core + "***";
        }
        else if (style.Bold)
        {
            core = "**" + core + "**";
        }
        else if (style.Italic)
        {
            core = "*" + core + "*";
        }

        if (style.Link is { } link)
        {
            core = $"[{core}]({EscapeUrl(link)})";
        }

        return leading + core + trailing;
    }

    /// <summary>
    /// Escapes the characters that are syntax wherever they appear.
    /// </summary>
    /// <remarks>
    /// Deliberately a short list. Escaping every character that could be
    /// syntax somewhere fills ordinary prose with backslashes that every other
    /// Markdown tool renders literally, so only the ones that really would be
    /// read as markup mid-sentence are escaped.
    /// </remarks>
    internal static string EscapeInline(string text)
    {
        var result = new StringBuilder(text.Length + 8);

        for (var i = 0; i < text.Length; i++)
        {
            var c = text[i];

            if (c is '\\' or '*' or '`' or '[' or ']' or '<' or '>' or '|'
                || (c == '_' && !InsideAWord(text, i))
                || (c == '~' && NextTo(text, i, '~')))
            {
                result.Append('\\');
            }

            result.Append(c);
        }

        return result.ToString();
    }

    /// <summary>
    /// Whether this character has a letter or digit on both sides.
    /// </summary>
    /// <remarks>
    /// An underscore inside a word is not emphasis in any Markdown that
    /// matters - CommonMark says so explicitly, so that snake_case survives
    /// being written by hand. Escaping it anyway is correct but turns
    /// <c>some_variable_name</c> into <c>some\_variable\_name</c>, and a file
    /// that cannot be read as plain text is a Markdown file that has lost its
    /// only advantage over the other formats.
    /// </remarks>
    private static bool InsideAWord(string text, int index) =>
        index > 0
        && index + 1 < text.Length
        && char.IsLetterOrDigit(text[index - 1])
        && char.IsLetterOrDigit(text[index + 1]);

    /// <summary>Whether the character on either side is this one.</summary>
    /// <remarks>
    /// Used for tildes: one is ordinary punctuation ("~5 minutes"), two in a
    /// row are strikethrough, so only a doubled one needs the backslash.
    /// </remarks>
    private static bool NextTo(string text, int index, char c) =>
        (index > 0 && text[index - 1] == c)
        || (index + 1 < text.Length && text[index + 1] == c);

    /// <summary>
    /// Escapes a marker that would be read as a block of its own because it
    /// stands at the start of a line.
    /// </summary>
    /// <remarks>
    /// <see cref="EscapeInline"/> deals with what is syntax anywhere in a line.
    /// This deals with what is syntax only at the beginning of one, which
    /// cannot be decided while the text of a run is being escaped: by then it
    /// is not yet known where in the line the run will land.
    /// <para>
    /// Every line is treated separately, because a paragraph can hold line
    /// breaks, and each of those starts a line as far as a Markdown reader is
    /// concerned. The usual trick is used for a numbered list: the delimiter
    /// is escaped rather than the digits, so "1. two" goes out as "1\. two",
    /// which reads as itself and renders as itself.
    /// </para>
    /// </remarks>
    internal static string EscapeBlockStarts(string body)
    {
        if (body.Length == 0)
        {
            return body;
        }

        var lines = body.Split('\n');

        for (var i = 0; i < lines.Length; i++)
        {
            lines[i] = EscapeOneLineStart(lines[i]);
        }

        return string.Join('\n', lines);
    }

    private static string EscapeOneLineStart(string line)
    {
        // Leading spaces are not touched - they cannot be escaped - but the
        // marker after them can be.
        var start = line.Length - line.TrimStart(' ').Length;
        var rest = line[start..];

        if (rest.Length == 0)
        {
            return line;
        }

        var prefix = line[..start];

        // A heading, a bullet, or a quote. A bullet needs the space after it:
        // "-5 degrees" is not a list.
        if (rest[0] == '#' || (rest[0] is '-' or '+' && rest.Length > 1 && rest[1] == ' '))
        {
            return prefix + '\\' + rest;
        }

        // A line of nothing but dashes or equals signs turns the paragraph
        // above it into a heading, and three or more dashes are a rule.
        var trimmed = rest.TrimEnd();

        if (trimmed.Length > 1
            && (trimmed.All(c => c == '-') || trimmed.All(c => c == '=')))
        {
            return prefix + '\\' + rest;
        }

        // A numbered list: digits, then "." or ")", then a space.
        var digits = 0;

        while (digits < rest.Length && char.IsAsciiDigit(rest[digits]))
        {
            digits++;
        }

        if (digits is > 0 and <= 9
            && digits + 1 < rest.Length
            && rest[digits] is '.' or ')'
            && rest[digits + 1] == ' ')
        {
            return prefix + rest[..digits] + '\\' + rest[digits..];
        }

        return line;
    }

    /// <summary>
    /// A URL for a Markdown link or image target.
    /// </summary>
    /// <remarks>
    /// Only the characters that would end the target early are escaped. The
    /// obvious Uri.EscapeUriString is obsolete and would mangle a URL that is
    /// already escaped, and EscapeDataString is for query components - it
    /// escapes the slashes and the colon too, which turns a URL into nonsense.
    /// Markdown only needs spaces, parentheses and angle brackets dealt with.
    /// </remarks>
    internal static string EscapeUrl(string url)
    {
        var text = new StringBuilder(url.Length + 8);

        foreach (var c in url)
        {
            switch (c)
            {
                case ' ':
                    text.Append("%20");
                    break;
                case '(':
                    text.Append("%28");
                    break;
                case ')':
                    text.Append("%29");
                    break;
                case '<':
                    text.Append("%3C");
                    break;
                case '>':
                    text.Append("%3E");
                    break;
                default:
                    text.Append(c);
                    break;
            }
        }

        return text.ToString();
    }

    internal static string ExtensionFor(string mime) => mime.ToLowerInvariant() switch
    {
        "image/png" => ".png",
        "image/jpeg" or "image/jpg" => ".jpg",
        "image/gif" => ".gif",
        "image/bmp" => ".bmp",
        "image/tiff" => ".tif",
        "image/webp" => ".webp",
        _ => ".png",
    };
}
